for (const [name, room, principle] of [
 ['Water clock','Measuring and time','floating-and-sinking'],
 ['Door closer','Doors and daily life','springs'],
 ['Washing machine','Cleaning cupboard','rotating-wheels'],
 ['Unicycle','Play and everyday objects','rotating-wheels'],
 ['Wax thermostat','Heating and cooling','heat-and-movement'],
]) {
 const id=name.toLowerCase().replace(/[^a-z0-9]+/g,'-');
 if(!neighborhoodCatalog.entries.some(entry=>entry.id===id)){
  neighborhoodCatalog.groups.push({id,place:'home',room,principle,relatedStudies:[],items:[name]});
  neighborhoodCatalog.entries.push({id,name,group:id});
 }
}

